import {matchingGameMarkup,mountMatchingGame} from './matching-view.js';
import {LESSONS,quadraticValue,quadraticExtrema,torqueBalance,ART_BACKGROUNDS,ART_FLOWER,HEALTH_CARDS,healthCheck,SPORT_SCENES,passClear} from './learning-model.js';
import {drawQuadratic,drawTorque,drawArt,drawPass} from './learning-draw.js';
const $=s=>document.querySelector(s),all=s=>document.querySelectorAll(s);
const pressed=(selector,value,key)=>all(selector).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset[key]===String(value))));
const canvas=(id,label)=>`<canvas id="${id}" class="learning-canvas" width="640" height="360" role="img" aria-label="${label}"></canvas>`;
const feedback=()=>'<p id="learning-status" class="learning-feedback" role="status" aria-live="polite">움직여 보고, 달라진 것을 살펴봐요</p>';
const say=t=>{$('#learning-status').textContent=t;};
const finish='<p class="caption">시간 제한과 점수는 없어요. 언제든 닫고 다시 놀 수 있어요. 이번 탐색은 저장되지 않아요.</p><div class="school-tool-row"><button data-close>마을로 돌아가기</button></div>';
function source(l){return `<details class="learning-source"><summary>어떤 고교 개념일까요?</summary><p>${l.subject} · [${l.standard}]</p><p>${l.connection}</p><p class="caption">${l.location}</p><p><a href="${l.source}" target="_blank" rel="noopener noreferrer">교육과정 원문 안내</a></p><p class="caption">${l.limit}</p><p class="caption">과목의 일부를 가볍게 탐색하는 활동이에요. 학교별 이수 학년은 다르며, 이 놀이만으로 성취기준 전체를 평가하거나 학습효과를 보장하지 않아요.</p></details>`;}
export function createLearningTools({ui,applyArt=()=>{},getAudio=null}){
 const open=(id,body,mount)=>{const l=LESSONS[id];return ui.workshop(l.title,`<div class="learning-workspace"><p class="learning-kicker">${l.concept}</p>${body}${source(l)}${finish}</div>`,mount);};
 function math(){let domainIndex=0,x=-1,found=[[false,false],[false,false]];const domains=[[-1,4],[2,4]];
  open('math',`<p>별을 곡선 위로 움직여 가장 낮은 곳과 높은 곳을 찾아봐요.</p><div class="school-tool-row"><button data-domain="0" aria-pressed="true">길 1 · −1부터 4</button><button data-domain="1" aria-pressed="false">길 2 · 2부터 4</button></div><p class="learning-equation">y = (x − 1)² − 4</p>${canvas('learning-graph','닫힌 구간에서 별을 움직이는 이차함수 그래프')}<label class="school-slider" for="learning-x">별의 x<input id="learning-x" type="range" min="-1" max="4" step="0.1" value="-1"><output id="learning-coordinate"></output></label><p class="caption">양 끝도 포함돼요. 눈금 사이의 값도 가능해요.</p><div class="school-tool-row"><button id="learning-min">이곳이 가장 낮아요</button><button id="learning-max">이곳이 가장 높아요</button><button id="learning-reset">다시 탐색</button></div>${feedback()}<p id="math-found"></p><p class="learning-question">꼭짓점이 길 밖에 있으면, 가장 낮은 곳은 어디일까요?</p>`,()=>{
   const c=$('#learning-graph'),s=$('#learning-x');const draw=()=>{drawQuadratic(c.getContext('2d'),{domain:domains[domainIndex],x});const y=quadraticValue(x);$('#learning-coordinate').textContent=`x ${x.toFixed(1)} · 높이 ${y.toFixed(2)}`;c.setAttribute('aria-label',`구간 ${domains[domainIndex].join('부터 ')}. 현재 x ${x}, 높이 ${y.toFixed(2)}`);$('#math-found').textContent=found.map((a,i)=>`길 ${i+1}: ${a[0]?'최소 발견':'최소 탐색 중'} / ${a[1]?'최대 발견':'최대 탐색 중'}`).join(' · ');};
   s.oninput=()=>{x=Number(s.value);draw();};all('[data-domain]').forEach(b=>b.onclick=()=>{domainIndex=Number(b.dataset.domain);const d=domains[domainIndex];x=d[0];s.min=d[0];s.max=d[1];s.value=String(x);pressed('[data-domain]',domainIndex,'domain');say(domainIndex?'길이 줄었어요. 이번에는 x=1까지 갈 수 없어요. 양 끝을 살펴봐요.':'별을 움직여 두 끝과 곡선의 낮은 곳을 비교해요.');draw();});
   const check=which=>{const key=which==='min'?0:1,e=quadraticExtrema(domains[domainIndex])[which];if(Math.abs(quadraticValue(x)-e.y)<1e-8){found[domainIndex][key]=true;say(`${which==='min'?'최솟값':'최댓값'} ${e.y}를 찾았어요. x=${e.x}예요.${domainIndex&&which==='min'?' 꼭짓점에 갈 수 없어 왼쪽 끝에서 가장 낮아요.':''}${found.flat().every(Boolean)?' 같은 곡선도 허용된 길에 따라 최솟값이 달라졌어요.':''}`);}else say('다른 위치의 높이도 비교해봐요. 허용된 길의 양 끝과, 갈 수 있는 꼭짓점을 살펴봐요.');draw();};$('#learning-min').onclick=()=>check('min');$('#learning-max').onclick=()=>check('max');$('#learning-reset').onclick=()=>{found=[[false,false],[false,false]];all('[data-domain]')[0].onclick();};draw();
  });
 }
 function science(){let mass=2,distance=1,balanced=new Set();open('science',`<p>오른쪽 1 kg 추를 다른 홈으로 옮겨봐요. 가벼운 추도 균형을 맞출 수 있을까요?</p>${canvas('learning-torque','받침점 양쪽의 추와 회전 방향 모형')}<div class="school-tool-row" role="group" aria-label="왼쪽 추"><button data-mass="2" aria-pressed="true">왼쪽 2 kg</button><button data-mass="1" aria-pressed="false">왼쪽도 1 kg</button></div><div class="school-tool-row" role="group" aria-label="오른쪽 추 거리">${[1,2,3].map(d=>`<button data-distance="${d}" aria-pressed="${d===1}">오른쪽 ${d} m</button>`).join('')}</div><p id="torque-values"></p>${feedback()}<p class="learning-question">추의 무게가 같을 때, 거리를 늘리면 돌림힘은?</p><div class="school-tool-row"><button data-torque-answer="more">커져요</button><button data-torque-answer="same">그대로예요</button></div>`,()=>{const draw=()=>{const r=torqueBalance(mass,distance);drawTorque($('#learning-torque').getContext('2d'),{mass,distance});$('#torque-values').textContent=`왼쪽 ${mass*9.8} N × 1 m = ${r.leftNm.toFixed(1)} N·m · 오른쪽 9.8 N × ${distance} m = ${r.rightNm.toFixed(1)} N·m`;$('#learning-torque').setAttribute('aria-label',`왼쪽 ${mass} kg, 1 m. 오른쪽 1 kg, ${distance} m. ${r.direction==='level'?'수평':r.direction==='left'?'왼쪽이 내려가는 방향':'오른쪽이 내려가는 방향'}`);if(r.net===0){balanced.add(mass);say(`균형이에요! 반시계 ${r.leftNm.toFixed(1)} − 시계 ${r.rightNm.toFixed(1)} = 0 N·m. 받침이 ${r.supportN.toFixed(1)} N으로 지지해 알짜힘도 0이에요.${balanced.size<2?' 왼쪽 추도 바꿔 다시 비교해봐요.':' 두 무게 조건의 균형을 비교했어요.'}`);}else say(`${r.direction==='left'?'왼쪽':'오른쪽'}이 내려가는 방향이에요. 반시계 방향을 +로 두면 합은 ${r.net>0?'+':''}${r.net.toFixed(1)} N·m예요.`);};all('[data-mass]').forEach(b=>b.onclick=()=>{mass=Number(b.dataset.mass);pressed('[data-mass]',mass,'mass');draw();});all('[data-distance]').forEach(b=>b.onclick=()=>{distance=Number(b.dataset.distance);pressed('[data-distance]',distance,'distance');draw();});all('[data-torque-answer]').forEach(b=>b.onclick=()=>say(b.dataset.torqueAnswer==='more'?'같은 힘이라도 받침점에서 멀어질수록 회전시키는 효과가 커져요. 두 무게 조건에서 균형도 찾아봐요.':'무게를 그대로 두고 오른쪽 거리를 1 m, 2 m, 3 m로 바꾸어 표시된 N·m를 비교해봐요.'));draw();});}
 function art(){let backgrounds=[0,1],intent='눈에 띄는 꽃';open('art',`<p>두 꽃의 색은 같아요. 배경만 바꾸어 표현 효과를 비교해봐요.</p><div class="learning-art-pair">${['A','B'].map((n,i)=>`<section><h3>그림 ${n}</h3>${canvas('art-'+n,'동일한 노란 꽃과 배경 '+n)}<label class="learning-select">배경 ${n}<select data-art-bg="${i}">${ART_BACKGROUNDS.map((p,j)=>`<option value="${j}" ${j===i?'selected':''}>${p.label}</option>`).join('')}</select></label></section>`).join('')}</div><label class="learning-select">표현 의도<select id="art-intent"><option>눈에 띄는 꽃</option><option>차분하게 어울리는 꽃</option></select></label><div class="school-tool-row"><button data-art-apply="0">A를 이젤에 놓기</button><button data-art-apply="1">B를 이젤에 놓기</button></div>${feedback()}<p class="learning-question">꽃을 바꾸지 않았는데, 배경 때문에 달라 보이는 부분이 있나요?</p>`,()=>{const draw=()=>{['A','B'].forEach((n,i)=>{drawArt($('#art-'+n).getContext('2d'),backgrounds[i]);$('#art-'+n).setAttribute('aria-label',`그림 ${n}: 꽃 ${ART_FLOWER}, 배경 ${ART_BACKGROUNDS[backgrounds[i]].label}`);});say(`두 꽃은 같은 색 값 ${ART_FLOWER}예요. 주변과의 대비를 바꾸어 “${intent}”의 느낌을 찾아봐요. 아름다움에는 정해진 답이 없어요.`);};all('[data-art-bg]').forEach(n=>n.onchange=()=>{backgrounds[Number(n.dataset.artBg)]=Number(n.value);draw();});$('#art-intent').onchange=e=>{intent=e.target.value;draw();};all('[data-art-apply]').forEach(n=>n.onclick=()=>{const i=Number(n.dataset.artApply);applyArt($('#art-'+['A','B'][i]));say(`그림 ${['A','B'][i]}를 이젤에 놓았어요. 선택한 의도는 “${intent}”이에요. 기존 그림 대신 이번 방문 동안 보여요.`);});draw();});}
 function health(){let id='a',revealed=false,tray='',reason='',done=new Set();open('health',`<p>가상 자료 3장을 뒤집어 보고, 확인할 단서가 있는 쟁반으로 옮겨봐요.</p><div class="school-tool-row">${HEALTH_CARDS.map(c=>`<button data-health-card="${c.id}" aria-pressed="${c.id==='a'}">자료 ${c.id.toUpperCase()}</button>`).join('')}</div><section class="learning-paper"><span class="caption">가상 연습 자료</span><h3 id="health-title"></h3><p id="health-front"></p><button id="health-flip">뒤쪽 단서 펼치기</button><p id="health-back" hidden></p></section><div class="learning-trays" role="group" aria-label="자료 놓을 쟁반"><button data-health-tray="start" aria-pressed="false">검토를 시작할 수 있음</button><button data-health-tray="check" aria-pressed="false">추가 확인이 필요함</button></div><p id="health-placement"></p><label class="learning-select">이유 토큰<select id="health-reason"><option value="">단서를 골라요</option value="author">작성자·근거를 찾아야 해요</option><option value="traceable">출처·근거·범위를 따라 확인할 수 있어요</option><option value="original">원문·날짜·앞뒤 맥락을 찾아야 해요</option><option value="popular">인기가 많으니 맞을 거예요</option></select></label><div class="school-tool-row"><button id="health-check">단서와 이유 이어 보기</button></div>${feedback()}<p id="health-progress"></p><p class="learning-question">더 확인하려면 무엇을 찾아봐야 할까요?</p>`,()=>{const update=()=>{const c=HEALTH_CARDS.find(c=>c.id===id);$('#health-title').textContent=c.title;$('#health-front').textContent=c.front;$('#health-back').textContent=c.back;$('#health-back').hidden=!revealed;$('#health-flip').textContent=revealed?'앞쪽으로 뒤집기':'뒤쪽 단서 펼치기';$('#health-placement').textContent=tray?`자료 ${id.toUpperCase()} → ${tray==='start'?'검토 시작':'추가 확인'} 쟁반`:'아직 쟁반을 고르지 않았어요';$('#health-progress').textContent=`살펴본 자료 ${done.size} / 3`;pressed('[data-health-card]',id,'healthCard');pressed('[data-health-tray]',tray,'healthTray');};all('[data-health-card]').forEach(n=>n.onclick=()=>{id=n.dataset.healthCard;revealed=false;tray='';reason='';$('#health-reason').value='';say('자료를 뒤집어 작성자, 날짜, 근거, 광고 단서를 살펴봐요.');update();});$('#health-flip').onclick=()=>{revealed=!revealed;update();};all('[data-health-tray]').forEach(n=>n.onclick=()=>{tray=n.dataset.healthTray;update();});$('#health-reason').onchange=e=>reason=e.target.value;$('#health-check').onclick=()=>{if(!revealed){say('자료를 뒤집어 뒤쪽 단서를 먼저 살펴봐요.');return;}const r=healthCheck(id,tray,reason);if(r.ok)done.add(id);say(r.text);update();};update();});}
 function sports(){let scene=0,slot=1,passed=false,opened=new Set();open('sports',`<p>공이 없는 친구를 1·2·3번 자리로 옮긴 뒤 패스해봐요. 수비가 바뀌면 같은 길도 달라져요.</p>${canvas('learning-pass','친구 자리 세 곳과 고정 수비의 패스 전술판')}<div class="school-tool-row">${[0,1,2].map(i=>`<button data-pass-slot="${i}" aria-pressed="${i===1}">친구 ${i+1}번 자리</button>`).join('')}</div><div class="school-tool-row"><button id="pass-send">패스해 보기</button><button id="pass-scene">수비 자리 바꾸기</button></div><p id="pass-scene-label"></p>${feedback()}<p class="learning-question">친구가 옆으로 움직이면 공이 지나갈 길은 어떻게 달라지나요?</p>`,()=>{const draw=()=>{drawPass($('#learning-pass').getContext('2d'),{scene,slot,passed});const s=SPORT_SCENES[scene];$('#learning-pass').setAttribute('aria-label',`장면 ${scene+1}, 친구 ${slot+1}번. ${passed?(passClear(s.passer,s.slots[slot],s.defenders)?'패스 길 열림':'수비 구역과 겹쳐 막힘'):'아직 패스하지 않음'}`);$('#pass-scene-label').textContent=`장면 ${scene+1} / 2 · 받는 친구 ${slot+1}번 자리 · 길을 연 장면 ${opened.size} / 2`;pressed('[data-pass-slot]',slot,'passSlot');};all('[data-pass-slot]').forEach(n=>n.onclick=()=>{slot=Number(n.dataset.passSlot);passed=false;draw();say('친구가 옮겨 갔어요. 패스해서 새 길을 확인해요.');});$('#pass-send').onclick=()=>{passed=true;const s=SPORT_SCENES[scene],clear=passClear(s.passer,s.slots[slot],s.defenders);if(clear)opened.add(scene);say(clear?'수비 구역과 겹치지 않는 길이 열렸어요. 받는 자리를 바꾸는 것도 팀을 돕는 움직임이에요.':'이 장면에서는 수비 구역이 길을 막아요. 친구 위치를 바꿔 다시 비교해봐요.');$('#learning-pass').setAttribute('aria-label',`장면 ${scene+1}, 친구 ${slot+1}번. ${clear?'패스 길 열림':'수비 구역과 겹쳐 막힘'}`);draw();};$('#pass-scene').onclick=()=>{scene=1-scene;passed=false;draw();say('수비가 다른 자리로 옮겼어요. 같은 친구 자리의 패스 길부터 비교해봐요.');};draw();});}
 function language(){ui.workshop(LESSONS.language.title,matchingGameMarkup(),mountMatchingGame);}
 const activities={math,science,art,health,sports,language};return{open(id){return activities[id]?.();}};
}
